      "proposed_laureates": ["Immanuel Bloch", "Markus Greiner", "Peter Zoller"],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled quantum simulation of interacting many-body systems experimentally accessible.",
        "attribution": "Bloch and Greiner established landmark experimental capabilities, while Zoller provided foundational theoretical direction for quantum simulation with atoms.",
        "maturity": "The methods are well confirmed and widely used, although the full goal of solving difficult material problems remains in progress.",
        "uncertainties": ["Juan Ignacio Cirac and Tilman Esslinger also made major contributions, and credit depends on how the discovery is framed."]
      }
